\begin{thm}\label{T3.1}
Let $X$ be an Asplund space and $\Omega_1$, \ldots, $\Omega_m$ be closed.
\begin{enumerate}
\item
$\bold{\Omega}$ is subregular at $\bar x$ if there exist positive numbers $\alpha$ and $\delta$ such that, for any $\rho\in ]0,\delta[$, $x\in B_{\rho}(\bar x)$, $\omega_i\in\Omega_i\cap B_{\rho}(x)$ $(i=1,\ldots,m)$ with $\omega_i\neq x$ for some ${i\in\{1,\ldots,m\}}$, there is an $\varepsilon>0$ such that, for any $x'\in B_{\varepsilon}(x)$, $\omega'_i\in\Omega_i\cap B_{\varepsilon}(\omega_i)$, $x_{i}^*\in N_{\Omega_i}(\omega_i') +\rho\B^*$ $(i=1,\ldots,m)$
satisfying
\begin{gather}\notag
x_i^*=0
\quad\mbox{if}\quad
\norm{x'-\omega_i'}<\max_{1\le j\le m} \norm{x'-\omega_j'},
\\\notag
\langle x_i^*,x'-\omega_i'\rangle
\ge\|x_i^*\|(\|x'-\omega_i'\|-\varepsilon),
\\\label{=1}
\sum_{i=1}^m\|x_i^*\|=1,
\end{gather}
it holds
\begin{gather}\label{>al}
\left\|\sum\limits_{i=1}^m{x}_i^*\right\|>\alpha.
\end{gather}
\item
$\bold{\Omega}$ is uniformly regular at $\bar x$ if and only if there are positive numbers $\alpha$ and $\delta$ such that
\eqref{>al} holds true
for all $\omega_i\in\Omega_i\cap{B}_\delta(\bar{x})$ and
$x_i^*\in{N}_{\Omega_i}(\omega_i)$ $(i=1,\ldots,m)$ satisfying \eqref{=1}. \end{enumerate}
\end{thm}

