\begin{prop}\label{theorem11}
\begin{enumerate}
\item
$\bold{\Omega}$ is semiregular at $\bar x$ if and only if $\theta[\bold{\Omega}](\bar{x})>0$. Moreover, $\theta[\bold{\Omega}](\bar{x})$ is the exact upper bound of all numbers $\alpha$ such that (\ref{HR}) is satisfied.
\item
$\bold{\Omega}$ is subregular at $\bar x$ if and only if $\zeta[\bold{\Omega}](\bar{x})>0$. Moreover, $\zeta[\bold{\Omega}](\bar{x})$ is the exact upper bound of all numbers $\alpha$ such that (\ref{Hlr'}) is satisfied.
\item
$\bold{\Omega}$ is uniformly regular at $\bar x$ if and only if $\hat{\theta}[\bold{\Omega}](\bar{x})>0$. Moreover, $\hat{\theta}[\bold{\Omega}](\bar{x})$ is the exact upper bound of all numbers $\alpha$ such that (\ref{HUR}) is satisfied.
\end{enumerate}
\end{prop}

\begin{prop}\label{prJ}
For each $(x_1,\ldots,x_m)\in X^m$,
\begin{multline*}
J(x_1,\ldots,x_m)= \Biggl\{(x_1^*,\ldots,x_m^*)\in(X^*)^m:\; \sum_{i=1}^m\|x_i^*\|=1;\mbox{ either } x_i^*=0\\
\mbox{or }\left(\|x_i\|=\max_{1\le j\le m} \|x_j\|,\; x_i^*\in\|x_i^*\| J(x_i)\right)\; (i=1,\ldots,m)\Biggr\}.
\end{multline*}
\end{prop}

\begin{proof}
Let $\hat x:=(x_1,\ldots,x_m)\in X^m$, $\hat x^*:=(x_1^*,\ldots,x_m^*)\in(X^*)^m$.
Then
$${\|\hat x\|=\max_{1\le i\le m} \|x_i\|},\quad \|\hat x^*\|=\sum_{i=1}^m\|x_i^*\|,\quad \langle \hat x^*,\hat x\rangle=\sum_{i=1}^m\langle x_i^*,x_i\rangle.$$
Suppose $\|\hat x^*\|=1$, i.e., $\sum_{i=1}^m\|x_i^*\|=1$.
Then $\hat x^*\in J(\hat x)$ if and only if ${\sum_{i=1}^m\langle x_i^*,x_i\rangle=\|\hat x\|}$.
In its turn, the last equality holds true if and only if ${\langle x_i^*,x_i\rangle=\|x_i^*\|\cdot\|\hat x\|}$ for all $i=1,\ldots,m$.

Indeed, if $\langle x_i^*,x_i\rangle=\|x_i^*\|\cdot\|\hat x\|$ for all $i=1,\ldots,m$, then adding these $m$ equalities, we obtain $\sum_{i=1}^m\langle x_i^*,x_i\rangle=\|\hat x\|$.
Conversely, if $\langle x_i^*,x_i\rangle\ne\|x_i^*\|\cdot\|\hat x\|$, i.e., ${\langle x_i^*,x_i\rangle<\|x_i^*\|\cdot\|\hat x\|}$ for some $i\in\{1,\ldots,m\}$, then
$$
\sum_{j=1}^m\langle x_j^*,x_j\rangle =\langle x_i^*,x_i\rangle+\sum_{j\ne i}\langle x_j^*,x_j\rangle <\|x_i^*\|\cdot\|\hat x\|+\|\hat x\|\sum_{j\ne i} \|x_j^*\|=\|\hat x\|.
$$

Finally, $\langle x_i^*,x_i\rangle=\|x_i^*\|\cdot\|\hat x\|$ for some $i\in\{1,\ldots,m\}$ if and only if either $\|x_i\|=\|\hat x\|$ and $x_i^*\in\|x_i^*\| J(x_i)$ or $x_i^*=0$.
\qed\end{proof}

\begin{lem}\label{ll02}
Let $X$ be a normed space and
$\varphi(u,\hat u)=\|(u-u_1,\ldots,u-u_m)\|$, $u\in X$, $\hat u:=(u_1,\ldots,u_m)\in X^m$.
Suppose $x\in X$, $\hat x:=(x_1,\ldots,x_m)\in X^m$, and ${\hat v:=(x-x_1,\ldots,x-x_m)}\ne0$. Then
\begin{align*}
\sd\varphi(x,\hat x)\subseteq\bigl\{\left(x^*,\hat x^* =(x_1^*,\ldots,x_m^*)\right)\in &X^*\times (X^*)^m :\;\\
&-\hat x^*\in J(\hat v),\; x^*=-(x_{1}^*+\ldots+x_{m}^*)\bigr\}.
\end{align*}
\end{lem}

\begin{proof}
%Observe that $\varphi$ is a composition of the norm on $X^m$ and the linear continuous mapping $(x,\hat x)\mapsto(x_1-x,\ldots,x_m-x)$.
Let $\left(x^*,\hat x^* =(x_1^*,\ldots,x_m^*)\right)\in \sd\varphi(x,\hat x)$, i.e.,
$$
\|(u-u_1,\ldots,u-u_m)\|-\|(x-x_1,\ldots,x-x_m)\|\ge \langle x^*,u-x\rangle+\sum_{i=1}^m\langle x_i^*,u_i-x_i\rangle
$$
for any $u\in X$ and $\hat u:=(u_1,\ldots,u_m)\in X^m$.
In particular, with $u=x$ and $u_i=x_i-x_i'$ ($i=1,\ldots,m$) for an arbitrary $\hat x':=(x_1',\ldots,x_m')\in X^m$, we have
$$
\|\hat v+\hat x'\|-\|\hat v\|\ge-\langle\hat x^*,\hat x'\rangle,
$$
i.e., $-\hat x^*\in J(\hat v)$.
Similarly, with $u=x+x'$ and $u_i=x_i+x'$ ($i=1,\ldots,m$) for an arbitrary $x'\in X$, we have
$$
\left\langle x^*+\sum_{i=1}^mx_i^*,x'\right\rangle\le0,
$$
and consequently $x^*+x_{1}^*+\ldots+x_{m}^*=0$.
\qed\end{proof}

\begin{lem}\label{ll03}
Let $X$ be a normed space and $\hat\omega:=(\omega_1,\ldots,\omega_m)\in\widehat\Omega$.
Then ${N_{\widehat\Omega}(\hat\omega) =N_{\Omega_1}(\omega_1)\times\ldots\times N_{\Omega_m}(\omega_m)}$.
\end{lem}

\begin{proof}
follows directly from the definition of the Fr\'echet normal cone.
\qed\end{proof}

\begin{prop}\label{T3.1.1}
Let $X$ be a Banach space and $\Omega_1$, \ldots, $\Omega_m$ be closed.
\begin{enumerate}
\item
$\hat\zeta[\bold{\Omega}](\bar x)\le \zeta[\bold{\Omega}](\bar{x})$, where
\begin{equation}\label{strslo}
\hat\zeta[\bold{\Omega}](\bar x):= \lim_{\rho\downarrow0} \inflarge_{\substack{\norm{x-\bar x}<\rho\\ \hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega\\ 0<\max\limits_{1\le i\le m} \norm{x-\omega_i}<\rho}}
\zeta_{\rho}[\bold{\Omega}](x,\hat\omega)
\end{equation}
and, for $x\in X$ and $\hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega$,
\begin{equation}\label{rhoslo}
\zeta_{\rho}[\bold{\Omega}](x,\hat\omega):= \limsup_{\substack{(u,\hat v)\to(x,\hat\omega)\\(u,\hat v)\neq (x,\hat\omega)\\ \hat v=(v_1,\ldots,v_m)\in \widehat\Omega}} \frac{\left(\max\limits_{1\le i\le m} \norm{x-\omega_i}-\max\limits_{1\le i\le m} \norm{u-v_i}\right)_+}{\norm{(u,\hat v)-(x,\hat\omega)}_{\rho}}.
\end{equation}
\item
If $\hat\zeta[\bold{\Omega}](\bar x)>0$, then $\bold{\Omega}$ is subregular at $\bar x$.
\end{enumerate}
\end{prop}

\begin{proof}
(i)
Let $\zeta[\bold{\Omega}](\bar{x})<\alpha<\infty$. Choose a $\rho\in ]0,1[$ and set
\begin{equation}\label{28}
\eta:= \min\left\{\frac{\rho}{2},\frac{\rho}{\alpha},\rho^{\frac{2}{\rho}}\right\}.
\end{equation}
By \eqref{errcon}, there are $x'\in B_{\eta}(\bar x)$ and $\hat\omega'=(\omega_1',\ldots,\omega_m')\in \widehat\Omega$ such that
\begin{equation}\label{29}
   0<f(x',\hat\omega')<\alpha d\left(x',\bigcap_{i=1}^m\Omega_i\right).
\end{equation}
Denote $\varepsilon:=f(x',\hat\omega')$ and $\mu:=d\left(x',\bigcap_{i=1}^m\Omega_i\right)$. Then $\mu\le \norm{x'-\bar x}\le \eta\le \frac{\rho}{2}<1$.
Observe that $f$ is lower semicontinuous.
Applying to $f$ Lemma~\ref{l01} with $\varepsilon$ as above and
\begin{equation}\label{30}
\lambda:=\mu(1-\mu^{\frac{\rho}{2-\rho}}),
\end{equation}
we find points $x\in X$ and $\hat\omega=(\omega_1,\ldots,\omega_m)\in X^{m}$ such that
\begin{equation}\label{31}
   \norm{(x,\hat\omega)-(x',\hat\omega')}_{\rho}<\lambda,\; f(x,\hat\omega)\le f(x',\hat\omega'),
\end{equation}
and
\begin{equation}\label{32}
f(u,\hat v)+\frac{\varepsilon}{\lambda}\norm{(u,\hat v)-(x,\hat\omega)}_{\rho} \ge f(x,\hat\omega),
\end{equation}
for all $(u,\hat v)\in X\times X^{m}$.
Thanks to \eqref{31}, \eqref{30}, \eqref{28}, and \eqref{29}, we have
$$
\norm{x-x'}<\lambda <\mu \le \norm{x'-\bar x},
$$
\begin{equation}\label{33}
   d\left(x,\bigcap_{i=1}^m\Omega_i\right)\ge d\left(x',\bigcap_{i=1}^m\Omega_i\right)- \norm{x-x'}\ge \mu-\lambda =\mu^{\frac{2}{2-\rho}},
\end{equation}
\begin{equation}\label{34}
\norm{x-\bar x}\le \norm{x-x'}+\norm{x'-\bar x}<2\norm{x'-\bar x}\le 2\eta\le\rho,
\end{equation}
\begin{equation}\label{35}
f(x,\hat\omega)\le f(x',\hat\omega')<\alpha\mu\le \alpha\eta\le\rho.
\end{equation}
It follows from \eqref{33}, \eqref{34}, and \eqref{35} that
$$
\norm{x-\bar x}<\rho,\; \hat\omega\in \widehat\Omega,\; 0<\max\limits_{1\le i\le m} \norm{x-\omega_i}<\rho.
$$
Observe that $\mu^{\frac{\rho}{2-\rho}}\le \eta^{\frac{\rho}{2-\rho}}< \eta^{\frac{\rho}{2}}\le \rho$, and consequently, by \eqref{29} and \eqref{30},
$$
\frac{\varepsilon}{\lambda} <\frac{\alpha\mu}{\lambda} =\frac{\alpha}{1-\mu^{\frac{\rho}{2-\rho}}} <\frac{\alpha}{1-\rho}.
$$
Thanks to \eqref{32} and \eqref{f}, we have
$$
\max\limits_{1\le i\le m} \norm{x-\omega_i}-\max\limits_{1\le i\le m} \norm{u-v_i}\le \frac{\alpha}{1-\rho}\norm{(u,\hat v)-(x,\hat\omega)}_{\rho}
$$
for all $u\in X$ and $\hat v=(v_1,\ldots,v_m)\in \widehat\Omega$.
It follows that $\zeta_{\rho}[\bold{\Omega}](x,\hat\omega)\le \dfrac{\alpha}{1-\rho}$ and consequently
$$
\inflarge_{\substack{\norm{x-\bar x}<\rho\\\hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega\\ 0<\max\limits_{1\le i\le m} \norm{x-\omega_i}<\rho}}
\zeta_{\rho}[\bold{\Omega}](x,\hat\omega)\le \frac{\alpha}{1-\rho}.
$$
Taking limits in the last inequality as $\rho\downarrow 0$ and $\alpha\to \zeta[\bold{\Omega}](\bar{x})$ yields the claimed inequality.

(ii) follows from (i) and Proposition~\ref{theorem11}~(ii).
\qed\end{proof}

\begin{prop}\label{T3.1.2}
Let $X$ be an Asplund space and $\Omega_1$, \ldots, $\Omega_m$ be closed.
\begin{enumerate}
\item
$\hat\zeta^*_1[\bold{\Omega}](\bar x)\le \hat\zeta[\bold{\Omega}](\bar x)$, where $\hat\zeta[\bold{\Omega}](\bar x)$ is given by \eqref{strslo},
\begin{equation}\label{strsubslo'}
\hat\zeta^*_1[\bold{\Omega}](\bar x):= \lim_{\rho\downarrow 0} \inflarge_{\substack{\norm{x-\bar x}<\rho\\ \hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega\\ 0<\max\limits_{1\le i\le m} \norm{x-\omega_i}<\rho}}
\zeta_{\rho,1}^*[\bold{\Omega}](x,\hat\omega)
\end{equation}
and, for $x\in X$ and $\hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega$,
\begin{equation}\label{subrhoslo}
\zeta_{\rho,1}^*[\bold{\Omega}](x,\hat\omega):= \inflarge_{\substack{(x^*,\hat y^*)\in\partial f(x,\hat\omega)\\ \norm{\hat y^*}<\rho}}\norm{x^*}
\end{equation}
(with the convention that the infimum over the empty set equals $+\infty$).
\item
If $\hat\zeta^*_1[\bold{\Omega}](\bar x)>0$, then $\bold{\Omega}$ is subregular at $\bar x$.
\end{enumerate}
\end{prop}

\begin{proof}
Let $\hat\zeta[\bold{\Omega}](\bar x)< \alpha<\infty$.
Choose a $\beta\in ]\hat\zeta[\bold{\Omega}](\bar x),\alpha[$ and an arbitrary ${\rho>0}$.
Set ${\rho'=\min\{1,\alpha^{-1}\}\rho}$.
By \eqref{strslo} and \eqref{rhoslo}, one can find points $x\in X$ and ${\hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega}$ such that $\norm{x-\bar x}<\rho'$, $0<\max_{1\le i\le m} \norm{\omega_i-x}<\rho'$, and
$$
\max\limits_{1\le i\le m} \norm{x-\omega_i}-\max\limits_{1\le i\le m} \norm{u-v_i}\le \beta\norm{(u,\hat v)-(x,\hat\omega)}_{\rho'}
$$
for all $(u,\hat v)$ with $\hat v=(v_1,\ldots,v_m)\in \widehat\Omega$ near $(x,\hat\omega)$.
In other words, $(x,\hat\omega)$ is a local minimizer of the function
$$
(u,\hat v)\mapsto \max\limits_{1\le i\le m} \norm{u-v_i}+\beta\norm{(u,\hat v)-(x,\hat\omega)}_{\rho'}
$$
subject to $\hat v=(v_1,\ldots,v_m)\in \widehat\Omega$.
By definition \eqref{f}, this means that $(x,\hat\omega)$ minimizes locally the function
$$
(u,\hat v)\mapsto f(u,\hat v)+\beta\norm{(u,\hat v)-(x,\hat\omega)}_{\rho'},
$$
and consequently its Fr\'echet subdifferential at $(x,\hat\omega)$ contains zero.
Take an
$$
\varepsilon\in\Bigl]0,\min\{\rho-\norm{x-\bar x},\rho-\max_{1\le i\le m} \norm{x-\omega_i},\alpha-\beta\}\Bigr[.
$$
Applying Lemma~\ref{l02} and Lemma~\ref{ll01}~(ii), we can find points $x'\in X$, ${\hat\omega'=(\omega_1',\ldots,\omega_m')\in \widehat\Omega}$, and $(x^*,\hat y^*)\in \partial f(x',\hat\omega')$ such that $$\norm{x'-x}<\varepsilon,\quad 0<\max_{1\le i\le m} \norm{x'-\omega_i'}\le \max_{1\le i\le m} \norm{x-\omega_i}+\varepsilon,$$
$$\mbox{and}\quad\norm{(x^*,\hat y^*)}_{\rho'} =\|x^*\|+\|\hat y^*\|/\rho' <\beta+\varepsilon.$$
It follows that
$$\norm{x'-\bar x}<\rho,\;\; 0<\max_{1\le i\le m} \norm{x'-\omega_i'}<\rho,\;\; \norm{x^*}<\alpha,\;\mbox{ and }\; \norm{\hat y^*}<\rho'\alpha\le \rho.$$
Hence, $\zeta_{\rho,1}^*[\bold{\Omega}](x',\hat\omega')<\alpha$, and consequently $\hat\zeta^*_1[\bold{\Omega}](\bar x)<\alpha$.
By letting $\alpha\to \hat\zeta[\bold{\Omega}](\bar x)$, we obtain the claimed inequality.

(ii) follows from (i) and Proposition~\ref{T3.1.1}~(ii).
\qed\end{proof}

\begin{prop}\label{T3.1.3}
Let $X$ be an Asplund space and $\Omega_1$, \ldots, $\Omega_m$ be closed.
\begin{enumerate}
\item
$\hat\zeta^*_2[\bold{\Omega}](\bar x)\le \hat\zeta^*_1[\bold{\Omega}](\bar x)$, where $\hat\zeta^*_1[\bold{\Omega}](\bar x)$ is given by \eqref{strsubslo'},
\begin{equation}\label{c2}
\hat\zeta^{*}_2[\bold{\Omega}](\bar x):= \lim_{\rho\downarrow 0} \inf_{\substack{\norm{x-\bar x}<\rho\\ \hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega\\ 0<\max\limits_{1\le i\le m} \norm{x-\omega_i}<\rho}}
\lim_{\varepsilon\downarrow 0} \inf_{\substack{\norm{x'-x}<\varepsilon\\ \hat\omega'\in \widehat\Omega\\ \norm{\hat\omega'-\hat\omega}<\varepsilon}}
\zeta_{\rho,\varepsilon,2}^{*}[\bold{\Omega}] (x',\hat\omega')
\end{equation}
and, for $x\in X$ and $\hat\omega=(\omega_1,\ldots,\omega_m)\in \widehat\Omega$ with $(x-\omega_1,\ldots,x-\omega_m)\ne0$,
\begin{align}
\zeta_{\rho,\varepsilon,2}^{*}[\bold{\Omega}](x,\hat\omega):= \inf\Biggl\{
\left\|\sum\limits_{i=1}^m{x}_i^*\right\|:\,
&
x_{i}^*\in N_{\Omega_i}(\omega_i) +\rho\B^*\quad (i=1,\ldots,m),
\notag\\&
x_i^*=0
\quad\mbox{if}\quad
\norm{x-\omega_i}<\max_{1\le j\le m} \norm{x-\omega_j},
\notag\\&
\langle x_i^*,x-\omega_i\rangle
\ge\|x_i^*\|(\|x-\omega_i\|-\varepsilon),
\notag\\&
\sum_{i=1}^m\|x_i^*\|=1
\Biggr\}.\label{c2r}
\end{align}
\item
If $\hat\zeta^*_2[\bold{\Omega}](\bar x)>0$, then $\bold{\Omega}$ is subregular at $\bar x$.
\end{enumerate}
\end{prop}

\begin{proof}
(i)
Let $\rho>0$, $x\in X$, $\hat\omega:= (\omega_1,\ldots,\omega_m)\in\widehat\Omega$ with $\|x-\bar x\|<\rho$, ${0<\max_{1\le i\le m} \norm{x-\omega_i}<\rho}$, $(u^*,\hat v^*) \in\partial f(x,\hat\omega)$, where $f$ is given by \eqref{f}, and $\|\hat v^*\|<\rho$.
Denote $\hat v:=(x-\omega_1,\ldots,x-\omega_m)$.
Then $0<\|\hat v\|<\rho$.
Observe that function $f$ is the sum of two functions on $X^{m+1}$:
$$(x,\hat x)\mapsto \varphi(x,\hat x):= \|(x-x_1,\ldots,x-x_m)\|\quad\mbox{and}\quad(x,\hat x) \mapsto\delta_{\widehat\Omega}(\hat x),$$
where $\hat x:=(x_1,\ldots,x_m)$ and $\delta_{\widehat\Omega}$ is the indicator function of $\widehat\Omega$.
The first function is Lipschitz continuous while the second one is lower semicontinuous.
One can apply Lemma~\ref{l02}.
For any $\varepsilon>0$, there exist points $x'\in X$, $\hat x:=(x_1,\ldots,x_m)\in X^m$, $\hat\omega':=(\omega_1',\ldots,\omega_m') \in\widehat\Omega$, $\left(x^*,\hat y^*\right)\in\partial \varphi(x',\hat x)$, and $\hat\omega^*\in N_{\widehat\Omega}(\hat\omega')$ such that
\begin{gather}\notag
\|x'-x\|<\varepsilon,\quad \|\hat x-\hat\omega\|<\frac{\varepsilon}{4},\quad \|\hat\omega'-\hat\omega\|<\frac{\varepsilon}{4},
\\\label{est}
\|(u^*,\hat v^*)-(x^*,\hat y^*)-(0,\hat\omega^*)\|<\varepsilon.
\end{gather}
Taking a smaller $\varepsilon$ if necessary, one can ensure that $\hat v':=(x'-\omega_1',\ldots,x'-\omega_m')\ne0$, $\hat v'':=(x'-x_1,\ldots,x'-x_m)\ne0$, $\|\hat v^*\|+\varepsilon<\rho$
and,
for any $i=1,\ldots,m$, ${\norm{x'-x_i}<\max_{1\le j\le m} \norm{x'-x_j}}$ if and only if ${\norm{x'-\omega_i'}<\max_{1\le j\le m} \norm{x'-\omega_j'}}$.
By Lemma~\ref{ll02},
$$\hat x^*:=-\hat y^*\in J(\hat v'')
\quad\mbox{and}\quad
x^*=x_{1}^*+\ldots+x_{m}^*,$$
where
$\hat x^*=(x_1^*,\ldots,x_m^*)$.
By Proposition~\ref{prJ},
\begin{gather*}
\sum_{i=1}^m\|x_i^*\|=1,
\\
x_i^*=0
\quad\mbox{if}\quad
\norm{x'-\omega_i'}<\max_{1\le j\le m} \norm{x'-\omega_j'},
\end{gather*}
\begin{align*}
\langle x_i^*,x'-\omega_i'\rangle
&\ge\langle x_i^*,x'-x_i\rangle-\|x_i^*\|\,\|x_i-\omega_i'\| =\|x_i^*\|(\|x'-x_i\|-\|x_i-\omega_i'\|)
\\&
\ge\|x_i^*\|(\|x'-\omega_i'\|-2\|x_i-\omega_i'\|)
\ge\|x_i^*\|(\|x'-\omega_i'\|-\varepsilon) \quad(i=1,\ldots,m).
\end{align*}
Inequality \eqref{est} yields the estimates:
$\|u^*\|>\left\|{x}^*\right\|-\varepsilon$, $\left\|\hat x^*-\hat\omega^*\right\|<\|\hat v^*\|+\varepsilon<\rho$,
and consequently
$$
\|u^*\|> \left\|\sum\limits_{i=1}^m{x}_i^*\right\|-\varepsilon, \quad \hat x^*\in N_{\widehat\Omega}(\hat\omega') +\rho\B_m^*.
$$
It follows from Lemma~\ref{ll03} and definitions \eqref{subrhoslo} and \eqref{c2r} that
$$\zeta_{\rho,1}^*[\bold{\Omega}](x,\hat\omega)\ge \zeta_{\rho,\varepsilon,2}^*[\bold{\Omega}] (x',\hat\omega')-\varepsilon.$$
The claimed inequality is a consequence of the last one and definitions \eqref{strsubslo'} and \eqref{c2}.

(ii) follows from (i) and Proposition~\ref{T3.1.2}~(ii).
\qed\end{proof}

\begin{proof}\emph{of Theorem~\ref{T3.1}}
(i) follows from Proposition~\ref{T3.1.3}~(ii) and definitions \eqref{c2} and \eqref{c2r}.

(ii) is a consequence of \cite[Theorem~4]{Kru09.1}.
\qed\end{proof}

