The Fr\'echet normal cone to a set $\Omega\subset X$ at $x\in \Omega$ and the Fr\'echet subdifferential of a function $f:X \to\R_\infty:=\R\cup\{+\infty\}$ at a point $x$ with $f(x)<\infty$ are defined, respectively, by
\begin{equation*}
N_{\Omega}(x):= \left\{x^* \in X^* :\; \limsup_{u\to{x},\,u\in\Omega\setminus\{x\}} \frac {\langle x^*,u-x \rangle}{\|u-x\|} \leq 0 \right\},
\end{equation*}

\begin{equation*}
\partial f(x):=\left\{x^*\in X^*:\; \liminf_{\substack{u\to x,\,u\neq x}} \frac{f(u)-f(x)-\langle x^*,u-x\rangle}{\norm{u-x}}\ge 0\right\}.
\end{equation*}

The next definition introduces several regularity properties of $\bold{\Omega}$ at $\bar x$.

\begin{dfn}\label{HolderUR}
\begin{enumerate}
\item
$\bold{\Omega}$ is semiregular at $\bar x$ iff there exist positive numbers $\alpha$ and $\delta$ such that
\begin{equation}\label{HR}
\bigcap_{i=1}^m(\Omega_i-x_i)\  \bigcap\ B_{\rho}(\bar x) \neq \emptyset
\end{equation}
for all $\rho \in ]0,\delta[$ and all
$x_i\in{X}$ $(i=1,\ldots,m)$ such that $\max\limits_{1\leq i\leq m}\|x_i\| \le \alpha\rho$.

\item
$\bold{\Omega}$ is uniformly regular at $\bar x$ iff there exist positive numbers $\alpha$ and $\delta$ such that
\begin{equation}\label{HUR}
\bigcap_{i=1}^m(\Omega_i-\omega_i-x_i) \bigcap(\rho\B )\neq \emptyset
\end{equation}
for all $\rho \in ]0,\delta[$, $\omega_i \in \Omega_i \cap B_{\delta}(\bar{x})$, and all $x_i\in{X}$ $(i=1,\ldots,m)$ such that $\max\limits_{1\leq i\leq m}\|x_i\| \le \alpha\rho$.
\end{enumerate}
\end{dfn}

The regularity properties in Definition~\ref{HolderUR} can be equivalently defined using the following nonnegative constants which provide quantitative characterizations of these properties:
\begin{gather}\label{01.1}
\theta[\bold{\Omega}](\bar{x}):= \liminf_{\rho \downarrow 0} \dfrac{\theta_{\rho}[\bold{\Omega}](\bar{x})}{\rho},

where, for $\rho>0$ and $\delta>0$,
\begin{gather}\label{02.1}
\theta_{\rho}[\bold{\Omega}](\bar{x}):= \sup\left\{r \ge 0 :\; \bigcap_{i=1}^m (\Omega_i - x_i) \bigcap B_{\rho}(\bar{x}) \neq \emptyset,\; \forall x_i \in r\B \right\},

\\\label{02.2}
\zeta_{\rho,\delta}[\bold{\Omega}](\bar{x}):= \sup\left\{r\ge0 :\;\bigcap_{i=1}^m (\Omega_i+ r\B )\bigcap B_{\delta}(\bar x)\subseteq
\bigcap_{i=1}^m \Omega_i+\rho\B \right\}.
\end{gather}

\\\label{01.3}
\hat{\theta}[\bold{\Omega}](\bar{x}):= \liminf_{\omega_i\TO{\Omega_i}\bar{x},\rho\downarrow0} \dfrac{\theta_{\rho}[\Omega_1-\omega_1,\ldots,\Omega_m-\omega_m](0)}{\rho},
\end{gather}

\begin{prop}\label{theorem11}
\begin{enumerate}
\item
$\bold{\Omega}$ is semiregular at $\bar x$ if and only if $\theta[\bold{\Omega}](\bar{x})>0$. Moreover, $\theta[\bold{\Omega}](\bar{x})$ is the exact upper bound of all numbers $\alpha$ such that (\ref{HR}) is satisfied.

\item
$\bold{\Omega}$ is uniformly regular at $\bar x$ if and only if $\hat{\theta}[\bold{\Omega}](\bar{x})>0$. Moreover, $\hat{\theta}[\bold{\Omega}](\bar{x})$ is the exact upper bound of all numbers $\alpha$ such that (\ref{HUR}) is satisfied.
\end{enumerate}
\end{prop}

\\\label{errcon'}
\zeta[\bold{\Omega}](\bar{x})&= \quad\liminf_{\substack{x\to\bar{x}\\ x\notin \bigcap_{i=1}^m\Omega_i}}
\quad\frac{\max_{1\le i\le m} d(x,\Omega_i)}{d\Big{(}x,\bigcap_{i=1}^m\Omega_i\Big{)}}
\\\notag
&=\liminf_{\substack{x\to\bar{x}\\ \omega_i\TO{\Omega_i}\bar x\; (1\le i\le m)\\ x\notin \bigcap_{i=1}^m\Omega_i}}\frac{\max_{1\le i\le m}\norm{\omega_i-x}}{d\Big{(}x,\bigcap_{i=1}^m\Omega_i\Big{)}},

\begin{prop}\label{pr2}
\begin{align}\label{newcon}
\theta[\bold{\Omega}](\bar{x})&= \liminf_{\substack{x_i\to 0\; (1\le i\le m)\\ \bar x\notin \bigcap_{i=1}^m(\Omega_i-x_i)}}
\frac{\max_{1\le i\le m}\norm{x_i}}{d\Big{(}\bar x,\bigcap_{i=1}^m(\Omega_i-x_i)\Big{)}},

\\\label{vartheta}
\hat{\theta}[\bold{\Omega}](\bar{x})&= \liminf_{\substack{x\to\bar{x}\\x_i \to 0\;(1\le i\le m)\\x\notin\bigcap_{i=1}^m(\Omega_i-x_i)}} \frac{\max_{1\le i\le m}d(x+x_i,\Omega_i)} {d\Big{(}x,\bigcap_{i=1}^m(\Omega_i-x_i)\Big{)}}
\\\notag
&= \liminf_{\substack{x\to\bar{x}\\x_i\to0,\; \omega_i\TO{\Omega_i} \bar x\;(1\le i\le m)\\ x\notin\bigcap_{i=1}^m(\Omega_i-x_i)}} \frac{\max_{1\le i\le m} \norm{x+x_i-\omega_i}} {d\Big{(}x,\bigcap_{i=1}^m(\Omega_i-x_i)\Big{)}}.
\end{align}
\end{prop}

\emph{Equality \eqref{vartheta}} has been proved in \cite[Theorem 1]{Kru05.1}.
\qed
\end{proof}

The following simple fact of convex analysis is well known (cf., e.g., \cite[Corollary~2.4.16]{Zal02}).

\begin{lem}\label{ll01}
Let $(Y,\|\cdot\|)$ be a normed space.
\begin{enumerate}
\item
$\sd\|\cdot\|(y)=J(y)$ for any $y\ne0$.
\item
$\sd\|\cdot\|(0)=\B^*$.
\end{enumerate}
\end{lem}

In this section, along with the maximum type norm on $X^{m+1}=X\times X^m$, we are going to use another one depending on a parameter $\rho>0$ and defined as follows:
\begin{equation}\label{norm}
\norm{(x,\hat x)}_{\rho} :=\max\left\{\norm{x},\rho \norm{\hat x}\right\},\quad x\in X,\;\hat x\in X^m.
\end{equation}

It is easy to check that the corresponding dual norm has the following representation:
\begin{equation}\label{normd}
\norm{(x^*,\hat x^*)}_{\rho} =\|x^*\|+\rho^{-1}\|\hat x^*\|,\quad x^*\in X^*,\;\hat x^*\in (X^m)^*.
\end{equation}
Note that if, in \eqref{norm} and \eqref{normd}, $\hat x= (x_1,\ldots,x_m)$ and $\hat x^*= (x_1^*,\ldots,x_m^*)$ with $x_i\in X$ and $x_i^*\in X^*$ ($i=1,2,\ldots,m$), then $\|\hat x\|=\max_{1\le i\le m}\|x_i\|$ and $\|\hat x^*\|=\sum_{i=1}^m\|x_i^*\|$.

with function $f:X^{m+1}\to{\R}_\infty :={\R}\cup\{+\infty\}$ defined as
\begin{equation}\label{f}
f(x,\hat x)=\max_{1\le i\le m} \norm{x-x_i} + \delta_{\widehat\Omega}(\hat x),\quad x\in X,\; \hat x:=(x_1,\ldots,x_m)\in X^m,
\end{equation}
where $\delta_{\widehat\Omega}$ is the indicator function of $\widehat\Omega$: $\delta_{\widehat\Omega}(\hat x)=0$ if $\hat x\in\widehat\Omega$ and $\delta_{\widehat\Omega}(\hat x)=+\infty$ otherwise.

